// Number and markup formatting shared by every generator.
//
// The ddcnorth kit was first generated by Python, and its files are the reference the engine is
// tested against. These helpers reproduce Python's formatting exactly, so a regenerated kit is the
// same bytes as the one it replaces, not merely the same drawing.

/** Fixed decimals with trailing zeros dropped: Python's f'{v:.8f}'.rstrip('0').rstrip('.'). */
export const n = (value, digits = 8) => {
  const fixed = Number(value).toFixed(digits)
  if (!fixed.includes('.')) return fixed
  const trimmed = fixed.replace(/0+$/, '').replace(/\.$/, '')
  return trimmed === '-0' ? '0' : trimmed
}

/** Six-decimal variant used by the template and web builders. */
export const n6 = (value) => n(value, 6)

/** Python's html.escape(value, quote=True). */
export const escape = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#x27;')

/** Reads a dotted path ("symbol.viewBox.2") from an object. */
export const lookup = (source, path) => path.split('.').reduce((value, key) => (value == null ? undefined : value[key]), source)

/**
 * Fills `{path}` placeholders from a context object. Unknown paths are left as written, so a
 * typo shows up in the output instead of silently becoming "undefined".
 */
export const interpolate = (text, context) => String(text).replace(/\{([\w.-]+)\}/g, (match, path) => {
  const value = lookup(context, path)
  return value == null ? match : String(value)
})

/** "contact-name" → "Contact name". */
export const humanize = (id) => {
  const words = String(id).replace(/[-_]+/g, ' ').trim()
  return words.charAt(0).toUpperCase() + words.slice(1)
}

/** "Ministry of Forests" → "ministry-of-forests". */
export const slugify = (value) => String(value ?? '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')

/** Serialises an ordered attribute object, skipping null and undefined values. */
export const attrs = (object) => Object.entries(object)
  .filter(([, value]) => value != null)
  .map(([key, value]) => ` ${key}="${escape(value)}"`)
  .join('')
